/**
 * The adaptive spelling journey across all inflection rules, through the app's own logic (the calls the screens make).
 * Synthetic children establish software behaviour only, not educational effectiveness. Every journey word is
 * provisional content (generated by rule, not yet reviewed by an educator).
 */
import assert from "node:assert/strict";
import { test } from "node:test";
import { loadContent } from "./content.ts";
import { Learner } from "./learner.ts";
import { MemoryRepo } from "./store.ts";
import { fold } from "./state.ts";
import { testClock } from "./journey-sim.ts";
import { type Child, ruleError, runSpelling } from "./spelling-journey-sim.ts";
import { SPELLING_JOURNEY_POLICY, encounteredWords, explainAnswer, learningVector, ruleStates } from "./spelling-journey.ts";
import { countsAsVerified } from "../../../../packages/english-core/src/index.ts";

const content = loadContent();

async function child(name: string, clock = testClock()) {
  const repo = new MemoryRepo();
  const l = await Learner.create(content, repo, name, "guardian", clock, `p-${name}`);
  return { l, repo, clock };
}

const strong: Child = (w) => w.word;
/** Does not double short words until taught; with a hint after the lesson, gets it; after teaching, gets new words right. */
const learnsDoubling: Child = (w, ctx) => (w.rule === "double_short" && w.kind === "apply" && !ctx.taught.has("double_short") ? ruleError(w) : w.word);
/** Never doubles unless a worked example shows the answer. */
const neverDoubles: Child = (w, ctx) => (w.rule === "double_short" && w.kind === "apply" && ctx.hints < 3 ? ruleError(w) : w.word);

test("content: the journey bank is loaded with fixed roles, and check words are provisional questions, never practice", () => {
  const sj = content.spelling;
  assert.deepEqual(sj.order, ["plain", "es_plural", "double_short", "drop_e", "y_to_i", "stress_doubling", "no_double_unstressed", "exceptions"]);
  assert.ok(sj.words.size > 4000, `${sj.words.size} journey words`);
  for (const rj of sj.rules.values()) {
    assert.ok(rj.strategies.length >= 2, `${rj.rule}: at least two teaching approaches`);
    for (const st of rj.strategies) assert.ok(st.hints.length >= 2 && /this shows the answer/.test(st.hints.at(-1)!), `${rj.rule}/${st.id}: the last hint is a worked example`);
    for (const id of [...rj.assess, ...rj.retention, ...rj.contrast]) {
      const it = content.ctx.content.items.get(id)!;
      assert.equal(it.kind === "code" && it.evidence_status, "provisional", `${id} is provisional`);
      assert.ok(!(it as { generated?: unknown }).generated, `${id} is not practice-only`);
    }
    for (const id of rj.practice) assert.ok((content.ctx.content.items.get(id) as { generated?: unknown }).generated, `${id} is practice-only`);
  }
  // sources and licences travel with the runtime copy
  assert.deepEqual(sj.sources.map((s) => s.id).sort(), ["cmudict", "oewn", "scowl"]);
});

test("a strong speller gets a short check on every rule, no lessons, nothing claimed as mastered", async () => {
  const { l } = await child("strong");
  const t = await runSpelling(l, strong);
  assert.ok(t.steps.every((s) => s.startsWith("screen:")), t.steps.join(" | "));
  assert.equal(new Set(t.steps.map((s) => s.split(":")[1])).size, 8, "every rule had a first look");
  assert.ok(t.steps.length <= SPELLING_JOURNEY_POLICY.sessionAnswers);
  const v = learningVector(l.state, content, l.clock());
  assert.ok(v.rules.every((r) => r.provisional === "screened_right" && !r.verified), JSON.stringify(v.rules));
});

test("diagnosis, teaching, guided practice and a check on new words: a learner who learns from the lesson moves on", async () => {
  const { l } = await child("learner");
  const t = await runSpelling(l, learnsDoubling);
  const i = t.steps.indexOf("teach:double_short:worked_examples");
  assert.ok(i > 0, t.steps.join(" | "));
  assert.ok(t.steps.slice(0, i).some((s) => s === "screen:double_short:apply:wrong"), "the short check found the difficulty");
  assert.ok(t.steps.slice(i + 1, i + 5).every((s) => s.startsWith("guided:double_short")), "guided practice follows the lesson");
  const re = t.steps.slice(i).filter((s) => s.startsWith("reassess:double_short"));
  assert.ok(re.length >= 3 && re.every((s) => s.endsWith(":right")), `checked on new words: ${re}`);
  assert.ok(re.some((s) => s.includes(":contrast:")), "the check includes a word that must not double");
  // the mistake was named, because the answer was exactly the rule's misspelling
  assert.ok(t.explanations.some((e) => e.kind === "pattern" && e.tag === "no_doubling"));
  const r = learningVector(l.state, content, l.clock()).rules.find((x) => x.rule === "double_short")!;
  assert.equal(r.provisional, "moved_on");
  assert.equal(r.verified, false, "a demonstration on provisional words is never verified mastery");
});

test("check words never repeat a word the learner has met (lesson examples, practice, earlier checks), across sessions", async () => {
  const { l, clock } = await child("leak");
  await runSpelling(l, learnsDoubling);
  clock.days(3);
  await runSpelling(l, neverDoubles);
  const seen = new Set<string>();
  const taughtBy = new Map<string, string>();
  for (const e of l.events) {
    if (e.kind === "intervention" && e.rule) for (const w of content.spelling.rules.get(e.rule)!.teach) taughtBy.set(w.word, e.at);
    if (e.kind !== "presented") continue;
    const w = content.spelling.words.get(e.item.id);
    if (!w) continue;
    const check = e.purpose === "assessment" || e.purpose === "retention";
    if (check) {
      assert.ok(!seen.has(w.word), `${w.word} was checked after it had been met`);
      assert.ok(!taughtBy.has(w.word) || taughtBy.get(w.word)! > e.at, `${w.word} was a lesson example`);
      assert.ok(w.role === "assess" || w.role === "retention" || w.role === "contrast", `${w.word} (${w.role}) is not a check word`);
    }
    seen.add(w.word);
  }
  // encountered words include every lesson example taught
  const met = encounteredWords(l.state, content);
  for (const w of taughtBy.keys()) assert.ok(met.has(w));
});

test("no dead end: when approaches have not worked, the child gets practice with hints and the session moves on; nothing is claimed", async () => {
  const { l, clock } = await child("stuck");
  await runSpelling(l, neverDoubles);
  clock.days(1);
  const t = await runSpelling(l, neverDoubles);
  clock.days(1);
  const t3 = await runSpelling(l, neverDoubles);
  const all = [...t.steps, ...t3.steps];
  assert.ok(all.some((s) => s.startsWith("practice:double_short")), all.join(" | "));
  assert.ok(t3.end.step.kind === "summary");
  // other rules still get their turn after the practice round
  assert.ok(all.some((s) => s.startsWith("screen:drop_e")), "the session moves on to the next rule");
  const r = learningVector(l.state, content, l.clock()).rules.find((x) => x.rule === "double_short")!;
  assert.equal(r.provisional, "paused");
  assert.equal(r.demonstrated, "not_yet");
  assert.equal(l.spellingJourneyReport().rules.find((x) => x.rule === "double_short")!.help, "Optional: work through a few words together.");
});

test("uncertain answers are never given a misconception: 'not sure', unrelated words and slips get neutral feedback", () => {
  const w = content.spelling.words.get([...content.spelling.words.keys()].find((k) => k.startsWith("jrn.double_short.") && content.spelling.words.get(k)!.kind === "apply" && Object.keys(content.spelling.words.get(k)!.wrong).length)!)!;
  assert.equal(explainAnswer(content, w, Object.keys(w.wrong)[0], false).kind, "pattern");
  assert.equal(explainAnswer(content, w, "?", false).kind, "unsure");
  assert.equal(explainAnswer(content, w, "", false).kind, "unsure");
  assert.equal(explainAnswer(content, w, "elephant", false).kind, "neutral");
  const swapped = w.word.slice(0, 1) + w.word[2] + w.word[1] + w.word.slice(3);
  if (swapped !== w.word) assert.equal(explainAnswer(content, w, swapped, false).kind, "slip");
  for (const k of ["unsure", "neutral"]) assert.ok(!/doubl|vowel/.test(explainAnswer(content, w, k === "unsure" ? "?" : "elephant", false).text), "no rule-specific diagnosis");
});

test("persistence: leaving part-way and reopening from the stored record resumes the same step; a return after hours is a new session", async () => {
  const { l, repo, clock } = await child("resume");
  const t = await runSpelling(l, learnsDoubling, 200, 9);
  const before = await l.spellingJourney();
  const reopened = await Learner.open(content, repo, l.profileId, l.clock);
  const after = await reopened.spellingJourney();
  assert.deepEqual(after.step, before.step, `resumed at ${t.steps.at(-1)}`);
  assert.equal(after.session.event.session, before.session.event.session);
  // the rebuilt state is identical
  assert.equal(JSON.stringify([...ruleStates(fold(content, reopened.events), content, l.clock())]), JSON.stringify([...ruleStates(fold(content, l.events), content, l.clock())]));
  clock.days(2);
  const later = await reopened.startSpellingJourney();
  assert.notEqual(later.session.event.session, before.session.event.session, "a new session on a later day");
  // a teaching block left half-way is carried on in the new session
  if (before.step.kind === "guided") assert.ok(later.step.kind === "guided" || later.step.kind === "question");
});

test("a week after a rule was shown, the journey starts with a delayed check on words not seen before", async () => {
  const { l, clock } = await child("later");
  await runSpelling(l, learnsDoubling);
  clock.days(3);
  await runSpelling(l, learnsDoubling);
  const shown = ruleStates(l.state, content, l.clock()).get("double_short")!;
  clock.days(8);
  const t = await runSpelling(l, learnsDoubling);
  assert.ok(t.steps.some((s) => s.startsWith("retention:")), t.steps.join(" | "));
  if (shown.status === "demonstrated") assert.ok(t.steps.some((s) => s.startsWith("retention:double_short")), "the shown rule is checked again");
});

test("ability, evidence, demonstrated, provisional progression and verified mastery are separate; journey answers never move the estimate", async () => {
  const { l } = await child("vector");
  const before = learningVector(l.state, content, l.clock()).ability;
  await runSpelling(l, learnsDoubling);
  const v = learningVector(l.state, content, l.clock());
  assert.equal(v.ability.mean, before.mean, "provisional answers leave the production estimate unchanged");
  assert.equal(v.ability.source, "composite@1");
  assert.equal(v.experimental.enabled, false, "the research estimator is off");
  const d = v.rules.find((x) => x.rule === "double_short")!;
  assert.ok(d.evidence.total > 0 && d.evidence.provisional > 0 && d.evidence.validated === 0);
  assert.equal(d.verified, false);
  for (const r of ruleStates(l.state, content, l.clock()).values()) assert.equal(countsAsVerified(r), false);
  // exploring a later rule does not declare an earlier one known
  const plain = v.rules.find((x) => x.rule === "plain")!;
  assert.notEqual(plain.demonstrated, "shown_kept");
});

test("the doubling journey and its records are unchanged by the new journey", async () => {
  const { l } = await child("both");
  await runSpelling(l, learnsDoubling);
  const preview = l.journeyPreview();
  assert.ok(preview.step.kind === "question" || preview.step.kind === "summary" || preview.step.kind === "teach");
  assert.equal(content.journey.rule, "double_short");
  assert.equal(content.journey.assessOrder[0], "spl.infl.j02");
});

test("the rule estimate and its uncertainty update with every independent answer, not with practice or help, and survive a reload", async () => {
  const { l, repo } = await child("estimate");
  const est = (x: Learner) => learningVector(x.state, content, x.clock()).rules.find((r) => r.rule === "double_short")!.estimate;
  assert.equal(est(l).total, 0);
  assert.deepEqual(est(l).range80.map((x) => x <= 0.2 || x >= 0.8), [true, true], "wide before any answer");
  // answer until the first guided step, then compare what independent answers and practice did
  let v = await l.startSpellingJourney();
  let independent = 0;
  let guidedTotalBefore = -1;
  for (let i = 0; i < 60 && v.step.kind !== "summary"; i++) {
    const st = v.step;
    if (st.kind === "teach") await l.teachSpellingJourney(v);
    else if (st.kind === "question") {
      const before = est(l);
      await l.answerSpellingJourney(v, { kind: "typed", text: st.rule === "double_short" && st.word.kind === "apply" ? ruleError(st.word) : st.word.word });
      const after = est(l);
      if (st.rule === "double_short" && st.word.kind === "apply") {
        independent++;
        assert.equal(after.total, before.total + 1, "an independent answer on a new word is counted");
        assert.ok(after.mean < before.mean || before.total === 0, "a wrong answer lowers the estimate");
      }
    } else {
      guidedTotalBefore = est(l).total;
      await l.answerSpellingJourney(v, { kind: "typed", text: st.word.word });
      assert.equal(est(l).total, guidedTotalBefore, "guided practice never changes the estimate");
      break;
    }
    v = await l.spellingJourney();
  }
  assert.ok(independent >= 2 && guidedTotalBefore >= 2, "reached guided practice after independent answers");
  const e = est(l);
  assert.ok(e.range80[0] < e.mean && e.mean < e.range80[1], "the estimate carries its uncertainty");
  // persists: rebuilt from the stored record alone
  const reopened = await Learner.open(content, repo, l.profileId, l.clock);
  assert.deepEqual(est(reopened), e);
  // an estimate is never a mastery claim
  const rv = learningVector(reopened.state, content, reopened.clock()).rules.find((r) => r.rule === "double_short")!;
  assert.equal(rv.verified, false);
  assert.match(learningVector(reopened.state, content, reopened.clock()).ability.held, /content-validation gate/);
  assert.match(reopened.spellingJourneyReport().rules.find((r) => r.rule === "double_short")!.estimate!, /new words right/);
});
